import os
# Set thread limits before importing heavy libraries
os.environ['OMP_NUM_THREADS'] = '1'
os.environ['OPENBLAS_NUM_THREADS'] = '1'
os.environ['MKL_NUM_THREADS'] = '1'
os.environ['VECLIB_MAXIMUM_THREADS'] = '1'
os.environ['NUMEXPR_NUM_THREADS'] = '1'

from pathlib import Path
import numpy as np
from heraldo.serialization import load_results
from heraldo.analyze import print_results
from custom_targets import CustomFockTarget  # ensure the class is importable

def main():
    # Path to the results file generated by example_custom_target.py
    results_path = Path(__file__).parent / "custom_target_results.pkl"
    if not results_path.exists():
        print(f"Error: Results file '{results_path}' not found.")
        print("Please run 'example_custom_target.py' first to generate the results.")
        return

    # Load with reconstruction
    loaded = load_results(results_path, reconstruct=True)

    # Verify target reconstruction
    loaded_targets = loaded.get("targets")
    if not loaded_targets:
        print("No targets found in loaded results.")
        return

    # If it's a list, take the first (we only used one)
    if isinstance(loaded_targets, list):
        loaded_target = loaded_targets[0]
    else:
        loaded_target = loaded_targets

    # Recreate the original target manually for comparison (same parameters)
    # We need to know the parameters used in example_custom_target.py: coeffs=[1.0, 0.0, 1.0]
    original_target = CustomFockTarget(coeffs=[1.0, 0.0, 1.0])

    cutoff = 10  # must match the cutoff used in the example (10)
    ket_orig = original_target.get_target_ket(cutoff)
    ket_loaded = loaded_target.get_target_ket(cutoff)

    overlap = np.vdot(ket_orig, ket_loaded)
    fidelity = np.abs(overlap) ** 2
    print(f"Fidelity between original and reconstructed target ket: {fidelity:.6f}")
    assert np.isclose(fidelity, 1.0, atol=1e-6), "Target reconstruction failed!"

    print("✅ Reconstruction verified successfully.")
    print("\n--- Loaded Results Summary ---")
    print_results(loaded)

if __name__ == "__main__":
    main()